canvas = Path("src/sky/arcade/SkyDancerArcadeCanvasDemo.ts")
old_warning = '''      if (warning) {\n        const source = this.project(projectile.x, projectile.y, projectile.depth, cssWidth, cssHeight);\n        const pulse = .62 + Math.sin(snapshot.runTimeSeconds * 24 + projectile.id) * .2;\n        context.save();\n        context.strokeStyle = `rgba(255,49,94,${Math.max(.3, pulse)})`;\n        context.lineWidth = 2.2;\n        context.setLineDash([7, 6]);\n        context.beginPath();\n        context.moveTo(source.x, source.y);\n        context.lineTo(projected.x, projected.y);\n        context.stroke();\n        context.setLineDash([]);\n        context.lineWidth = 3;\n        context.beginPath();\n        context.arc(projected.x, projected.y, 18 + pulse * 9, 0, Math.PI * 2);\n        context.stroke();\n        context.restore();\n        continue;\n      }\n'''
new_warning = '''      if (warning) {\n        const source = this.project(projectile.x, projectile.y, projectile.depth, cssWidth, cssHeight);\n        const pulse = .62 + Math.sin(snapshot.runTimeSeconds * 24 + projectile.id) * .2;\n        const pattern = projectile.attackPattern ?? "snap";\n        const color = pattern === "homing" ? "255,79,222"\n          : pattern === "spread" ? "255,79,98"\n            : pattern === "crossfire" ? "255,214,92"\n              : "255,163,61";\n        const ringRadius = 18 + pulse * 9;\n        context.save();\n        context.strokeStyle = `rgba(${color},${Math.max(.36, pulse)})`;\n        context.lineWidth = pattern === "homing" ? 2.8 : 2.2;\n        context.setLineDash(pattern === "homing" ? [3, 4] : [7, 6]);\n        if (pattern === "spread") {\n          const fan = Math.max(24, cssWidth * .055);\n          for (const offset of [-fan, 0, fan]) {\n            context.beginPath();\n            context.moveTo(source.x, source.y);\n            context.lineTo(projected.x + offset, projected.y);\n            context.stroke();\n          }\n        } else {\n          context.beginPath();\n          context.moveTo(source.x, source.y);\n          context.lineTo(projected.x, projected.y);\n          context.stroke();\n        }\n        context.setLineDash([]);\n        if (pattern === "homing") {\n          context.save();\n          context.translate(projected.x, projected.y);\n          context.rotate(Math.PI / 4);\n          context.strokeRect(-ringRadius * .72, -ringRadius * .72, ringRadius * 1.44, ringRadius * 1.44);\n          context.restore();\n          context.beginPath();\n          context.arc(projected.x, projected.y, ringRadius * 1.22, 0, Math.PI * 2);\n          context.stroke();\n        } else if (pattern === "crossfire") {\n          context.beginPath();\n          context.moveTo(projected.x - ringRadius, projected.y - ringRadius);\n          context.lineTo(projected.x + ringRadius, projected.y + ringRadius);\n          context.moveTo(projected.x + ringRadius, projected.y - ringRadius);\n          context.lineTo(projected.x - ringRadius, projected.y + ringRadius);\n          context.stroke();\n        } else if (pattern === "spread") {\n          context.beginPath();\n          context.ellipse(projected.x, projected.y, ringRadius * 1.55, ringRadius * .72, 0, 0, Math.PI * 2);\n          context.stroke();\n        } else {\n          context.beginPath();\n          context.arc(projected.x, projected.y, ringRadius, 0, Math.PI * 2);\n          context.stroke();\n          context.beginPath();\n          context.moveTo(projected.x - ringRadius * 1.55, projected.y);\n          context.lineTo(projected.x - ringRadius * .9, projected.y);\n          context.moveTo(projected.x + ringRadius * .9, projected.y);\n          context.lineTo(projected.x + ringRadius * 1.55, projected.y);\n          context.stroke();\n        }\n        context.restore();\n        continue;\n      }\n'''
replace_once(canvas, old_warning, new_warning)
