css = Path("app/SkyDancerArcadeMode.module.css")
with css.open("a") as handle:
    handle.write(r'''\n\n/* Arcade Run V40.40: enemy attacks teach their dodge rule at a glance. */\n.attackDodgeCueV4040{position:absolute;z-index:12;left:50%;top:57%;transform:translate(-50%,-50%);display:grid;place-items:center;gap:2px;min-width:116px;padding:4px 10px 5px;border:1px solid rgba(255,163,61,.7);border-radius:999px;background:rgba(9,14,27,.58);box-shadow:0 0 18px rgba(255,140,60,.12);pointer-events:none;text-align:center;text-shadow:0 1px 5px rgba(0,0,0,.82)}\n.attackDodgeCueV4040 small{font-size:5px;font-weight:900;letter-spacing:.22em;color:rgba(255,255,255,.62)}\n.attackDodgeCueV4040 strong{font-size:9px;font-weight:1000;letter-spacing:.14em;color:#ffa33d}\n.attackDodgeCueV4040[data-pattern="crossfire"]{border-color:rgba(255,214,92,.72)}.attackDodgeCueV4040[data-pattern="crossfire"] strong{color:#ffd65c}\n.attackDodgeCueV4040[data-pattern="spread"]{border-color:rgba(255,79,98,.78)}.attackDodgeCueV4040[data-pattern="spread"] strong{color:#ff5969}\n.attackDodgeCueV4040[data-pattern="homing"]{border-color:rgba(255,79,222,.8);box-shadow:0 0 20px rgba(255,79,222,.16)}.attackDodgeCueV4040[data-pattern="homing"] strong{color:#ff68e2}\n@media (orientation:landscape) and (max-height:430px){.attackDodgeCueV4040{top:60%;min-width:102px;padding:3px 8px 4px}.attackDodgeCueV4040 small{font-size:4px}.attackDodgeCueV4040 strong{font-size:8px}}\n''')

Path("tests/sky-arcade-v4040-attack-language.test.ts").write_text(r'''import test from "node:test";\nimport assert from "node:assert/strict";\nimport { readFileSync } from "node:fs";\nimport { resolve } from "node:path";\nimport { skyDancerArcadeEnemyAttackPatternV4040, skyDancerArcadeEnemyDodgeHintV4040 } from "../src/sky/arcade/SkyDancerArcadeRuntime";\n\ntest("V40.40 maps enemy pressure to four learnable dodge languages", () => {\n  assert.equal(skyDancerArcadeEnemyAttackPatternV4040("drone", false, 1, .78), "snap");\n  assert.equal(skyDancerArcadeEnemyAttackPatternV4040("raider", false, 2, 1.04), "crossfire");\n  assert.equal(skyDancerArcadeEnemyAttackPatternV4040("gunship", false, 3, 1.2), "spread");\n  assert.equal(skyDancerArcadeEnemyAttackPatternV4040("missile-boat", false, 2, 1.52), "homing");\n  assert.equal(skyDancerArcadeEnemyDodgeHintV4040("snap"), "SIDE STEP");\n  assert.equal(skyDancerArcadeEnemyDodgeHintV4040("homing"), "LATE BREAK · TURBO");\n});\n\ntest("V40.40 carries attack language through WebGL, Canvas and HUD", () => {\n  const webgl = readFileSync(resolve(process.cwd(), "src/sky/arcade/SkyDancerArcadeWebGLDemo.ts"), "utf8");\n  const canvas = readFileSync(resolve(process.cwd(), "src/sky/arcade/SkyDancerArcadeCanvasDemo.ts"), "utf8");\n  const mode = readFileSync(resolve(process.cwd(), "app/SkyDancerArcadeMode.tsx"), "utf8");\n  assert.match(webgl, /arcade-enemy-warning-ring-v4040/);\n  assert.match(webgl, /attackPattern === "homing"/);\n  assert.match(canvas, /pattern === "spread"/);\n  assert.match(canvas, /pattern === "crossfire"/);\n  assert.match(mode, /attackDodgeCueV4040/);\n  assert.match(mode, /incomingAttackCue\.dodgeHint/);\n});\n''')
